// The ASCII spirit: a little creature of characters that wanders the contour map in
// circles. Within its reach the map turns to ASCII, and the characters scramble as it
// passes, then settle back into lines behind it. The pointer stirs the map the same way.
import {
  shader, picture, buffer, scene, table, vec2, vec3, vec4, int,
  time, dt, size, pointers, floor, length, smoothstep, mix, max, min, clamp,
  sin, cos, exp, fract, dot, step, mod, unsigned,
} from 'claude-code/shader'
import type { Buffer } from 'claude-code/shader'

// 5x6 bitmaps, bit = row * 5 + column. Generated by tools/font.js, in this order:
// 0-8 the density ramp  . : - + * = # % @
// 9-14 the letters      C L A U D E
// 15-22 the scramble    $ & ? / < > ! ~
const GLYPHS = table([
  4194304, 4194432, 491520, 139432064, 720353952, 1016800, 368389098, 852562291, 500889134,
  1007715390, 1041269793, 589284910, 488162865, 521717295, 1041284159,
  150616254, 748329254, 134357550, 35787024, 272697480, 71573634, 134353028, 444416,
], 'int')

const CELL = vec2(8, 11)  // one character cell, in points
const DOT = 1.3           // one font pixel, in points
const REACH = 160         // how far the spirit's effect spreads, in points
const LOOP = 70           // radius of the circles it walks, in points
const ORANGE = vec3(0.851, 0.467, 0.341)
const EMBER = vec3(0.984, 0.890, 0.839)
const GROUND = vec3(0.039, 0.039, 0.043)

function hash(a: vec2, b: number): number {
  return fract(sin(dot(a, vec2(12.9898, 78.233)) + b * 37.719) * 43758.5453)
}

// Drifts slowly across the whole map while it circles.
function spirit(): vec2 {
  const drift = vec2(0.5 + 0.34 * cos(time * 0.043), 0.5 + 0.3 * sin(time * 0.031 + 1.3))
  const turn = vec2(cos(time * 0.5), sin(time * 0.5)) * LOOP
  return vec2(drift * size + turn)
}

function reach(at: vec2): number {
  let k = smoothstep(REACH, REACH * 0.25, length(at - spirit()))
  for (const q of pointers) {
    k = max(k, smoothstep(120, 20, length(at - q.at)) * (1 - step(0.001, q.gone)))
  }
  return k
}

// The wake: what the spirit touched stays ASCII for a few seconds, then fades.
const wake: Buffer = buffer({ scale: 0.25, filter: 'linear' }, p => {
  const before = wake.sample(p.uv).r
  return vec4(max(before * exp(-dt * 0.45), reach(p.point)), 0, 0, 1)
})

// How bright the map is under one character cell: the brightest of four taps,
// so a hairline crossing the cell still counts.
function under(cell: vec2): number {
  let m = 0
  for (const i of [0, 1]) {
    for (const j of [0, 1]) {
      const c = scene.sample(vec2((cell + vec2(0.3 + i * 0.4, 0.3 + j * 0.4)) * CELL / size))
      m = max(m, max(c.r, max(c.g, c.b)))
    }
  }
  return m
}

export default shader({
  fps: 30,
  passes: [
    wake,
    picture(p => {
      const map = scene.sample(p.uv)
      const k = wake.sample(p.uv).r
      const cell = vec2(floor(p.point / CELL))
      const lum = under(cell)
      const tick = floor(time * 4)

      // what character: the ramp by brightness, CLAUDE along bright lines,
      // scrambled glyphs where the spirit is strongest
      const ramp = clamp(floor(lum * lum * 7), 0, 8)
      const word = mod(cell.x, 8)
      const lettered = step(0.62, lum) * step(word, 5.5) * step(0.5, hash(vec2(floor(cell.x / 8), cell.y), 3))
      // scramble where the spirit is now; its wake keeps the map's shape in ASCII
      const scrambled = step(hash(cell, tick), reach(p.point) * 0.16)
      let index = mix(ramp, 9 + word, lettered)
      index = mix(index, 15 + floor(hash(cell, tick + 91) * 8), scrambled)

      // the spirit's body: a bright knot of @ and * at its heart
      const d = length(vec2((p.point - spirit()) / CELL))
      const heart = 1 - step(0.9, d)
      const halo = (1 - step(2.4, d)) * (1 - heart) * step(hash(cell, tick + 7), 0.4)
      index = mix(index, 8, heart)
      index = mix(index, 4 + floor(hash(cell, tick + 3) * 2), halo)

      // dust, so the reach reads as a circle even over empty ground
      const dust = step(lum, 0.12) * step(hash(cell, floor(time * 1.5)), k * 0.12)
      const shown = max(step(0.12, lum), max(dust, max(heart, halo)))

      // the glyph's pixel under this point
      const inner = vec2(p.point - cell * CELL - vec2(0.75, 1.6))
      const gx = floor(inner.x / DOT)
      const gy = floor(inner.y / DOT)
      const inside = step(0, gx) * step(gx, 4) * step(0, gy) * step(gy, 5)
      const bits = GLYPHS.at(index)
      const on = (bits >> int(clamp(gy, 0, 5) * 5 + clamp(gx, 0, 4))) & 1
      const ink = inside * unsigned(on) * shown

      const warm = mix(ORANGE * (0.7 + lum * 0.6), EMBER, max(heart * 0.85, halo * 0.4 + scrambled * 0.15))
      const ascii = mix(GROUND, warm, ink)
      return vec4(mix(map.rgb, ascii, max(k * 0.9, max(heart, halo * 0.7))), 1)
    }),
  ],
})
